import{_ as t,o,c as r,a2 as s}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"Required Permissions","description":"ARM RBAC and Microsoft Graph permissions required by AzureScout.","frontmatter":{"description":"ARM RBAC and Microsoft Graph permissions required by AzureScout."},"headers":[],"relativePath":"guide/permissions.md","filePath":"guide/permissions.md"}'),a={name:"guide/permissions.md"};function i(n,e,d,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="required-permissions" tabindex="-1">Required Permissions <a class="header-anchor" href="#required-permissions" aria-label="Permalink to &quot;Required Permissions&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">This page covers inventory mode</p><p>This page describes the permission model for <strong>inventory mode</strong> (<code>Invoke-AzureScout</code> / <code>Test-AZSCPermissions</code>). <strong>Assessment mode</strong> (<code>-Assessment</code> / <code>Test-ScoutPermission</code>) uses a different, narrower model — see the note at the bottom of this page, or go straight to <a href="./../assessment/assessment-permissions.html">Assessment Permissions</a>. New here? See the <a href="./overview.html">Overview</a>.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>AzureScout requires three categories of permissions:</p><ol><li><strong>ARM (Azure Resource Manager)</strong> — RBAC role assignments on subscriptions</li><li><strong>Key Vault metadata</strong> — the metadata-only <code>Key Vault Reader</code> role when secret/key inventory is required</li><li><strong>Microsoft Graph API</strong> — Application or delegated permissions for Entra ID data</li></ol><h2 id="arm-permissions" tabindex="-1">ARM Permissions <a class="header-anchor" href="#arm-permissions" aria-label="Permalink to &quot;ARM Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Scope</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Reader</code></td><td>Subscription(s), or the tenant-root management group</td><td>Enumerate resources and read ARM properties</td></tr><tr><td><code>Management Group Reader</code></td><td>Tenant-root management group</td><td>Enumerate and expand the complete management-group hierarchy</td></tr><tr><td><code>Key Vault Reader</code></td><td>Each Key Vault, or an inherited scope that contains it</td><td>List secret/key metadata (names, tags, lifecycle attributes); cannot read secret values</td></tr></tbody></table><p>Azure&#39;s <code>Reader</code> role is the whole <strong>ARM control-plane</strong> ask. It is <code>Actions: */read</code> with an empty <code>NotActions</code> — a single wildcard over every control-plane read. There is no ARM collector in Scout that needs more than this, including roughly 130 of them that reach Azure through Azure Resource Graph (<code>Microsoft.ResourceGraph/resources/read</code> — also inside <code>Reader</code>&#39;s <code>*/read</code>, so the conclusion doesn&#39;t change, but a role list that names only the per-service actions is understating the ask by that one action).</p><div class="warning custom-block"><p class="custom-block-title">Assign Reader at management-group scope for the management-group and cross-subscription data</p><p>Subscription-scoped <code>Reader</code> silently returns an empty or flattened management-group hierarchy — no error, no warning. Assign it at the tenant-root management group if you want that data, or if you&#39;re running any assessment (assessment mode requires MG-root scope unconditionally — see <a href="./../assessment/assessment-permissions.html">Assessment Permissions</a>).</p><p>The management-group hierarchy uses <code>Get-AzManagementGroup -Expand -Recurse</code>. A live minimum-permission run confirmed that subscription-scoped Reader does not authorize that tenant operation. Assign <strong>Management Group Reader at the tenant-root management group</strong> when the full hierarchy is required. Scout records the missing hierarchy as a coverage gap and continues; it does not treat zero visible management groups as proof that none exist.</p></div><div class="danger custom-block"><p class="custom-block-title">Do not grant these three roles — they were removed from the ask</p><p><code>Security Reader</code>, <code>Monitoring Reader</code>, and <code>Cost Management Reader</code> (all <strong>Azure RBAC</strong> roles, not the Entra roles of the same name) used to be listed here as optional extras. They are not strict subsets of <code>Reader</code> — the precise statement is narrower: <strong>none of them grants anything Scout calls that <code>Reader</code> does not already grant.</strong></p><ul><li><strong><code>Monitoring Reader</code></strong> additionally grants <code>Microsoft.Support/*</code>, which includes support-ticket <strong>creation</strong> — a write, in a tool sold as read-only.</li><li><strong><code>Cost Management Reader</code></strong> carries the identical <code>Microsoft.Support/*</code>.</li><li><strong>Azure RBAC <code>Security Reader</code></strong> additionally grants five IoT Defender <code>/action</code> permissions, one of which downloads a password-reset file. Scout calls none of them. (The <strong>Entra</strong><code>Security Reader</code> role is unrelated and genuinely required for four Identity collectors — see the Graph table below.)</li></ul><p>The pre-flight checker no longer asks for any of the three, and <code>Test-AZSCPermissions</code> no longer reports them as missing.</p></div><div class="tip custom-block"><p class="custom-block-title">Key Vault object inventory needs metadata permission, never secret-value permission</p><p><code>KeyVaultSecrets</code> and <code>KeyVaultKeys</code> use the Key Vault LIST operations, which return metadata only: id, <code>contentType</code>, tags and the <code>attributes</code> block (<code>enabled</code>, <code>exp</code>, <code>nbf</code>, <code>created</code>, <code>updated</code>). Generic ARM <code>Reader</code> is not sufficient for a complete list: ARM sees only objects created as deployable ARM child resources. Assign built-in <strong><code>Key Vault Reader</code></strong> to supply <code>Microsoft.KeyVault/vaults/secrets/readMetadata/action</code> and the equivalent key metadata read. That role explicitly cannot read secret contents or private key material. Scout never invokes GET-secret, and it whitelists list-response fields before writing raw inventory. A Key Vault certificate has no separate list in Scout — it is materialised as a secret whose <code>contentType</code> is <code>application/x-pkcs12</code> or <code>application/x-pem-file</code>, and that secret&#39;s <code>attributes.exp</code> <strong>is</strong> the certificate&#39;s expiry, so certificate expiry is already present in the <code>KeyVaultSecrets</code> worksheet&#39;s <code>Kind</code>/<code>Expires</code> columns rather than a separate collector. See <code>src/collect/Get-ScoutArmChildResource.ps1</code> for the exact calls.</p></div><div class="tip custom-block"><p class="custom-block-title">Cost data needs no additional role beyond Reader</p><p><code>Microsoft.CostManagement/query/read</code> is inside <code>Reader</code>&#39;s <code>*/read</code>. If cost data still comes back empty with <code>Reader</code> assigned, the cause is a <strong>billing setting</strong>, not a permission: EA <strong>&quot;AO view charges&quot;</strong> or MCA <strong>&quot;Azure charges&quot;</strong> (the current name; older documentation calls it &quot;Allow Azure subscription users to view and optimize costs&quot;). Only an Enterprise Administrator (EA) or a <strong>Billing Profile Owner</strong> (MCA) can enable it — no Azure RBAC role, including <code>Cost Management Reader</code>, substitutes for it. See <a href="./troubleshooting.html">Troubleshooting</a>.</p></div><p>The pre-flight checker validates:</p><ul><li><strong>Subscription Enumeration</strong> — Can <code>Get-AzSubscription</code> return at least one subscription? (Fail if not)</li><li><strong>Role Assignment Read</strong> — Can <code>Get-AzRoleAssignment</code> read <code>Reader</code> on each target subscription? (Fail per subscription if <code>Reader</code> is missing there — <code>Reader</code> is the whole ARM ask, so there is no separate &quot;optional role missing&quot; Warn state any more)</li></ul><h2 id="microsoft-graph-permissions" tabindex="-1">Microsoft Graph Permissions <a class="header-anchor" href="#microsoft-graph-permissions" aria-label="Permalink to &quot;Microsoft Graph Permissions&quot;">​</a></h2><p>These are the Microsoft Graph <strong>application</strong> permissions a service principal needs for Entra ID inventory (<code>-Scope All</code> or <code>-Scope EntraOnly</code>). They are derived directly from the queries Scout&#39;s Entra collectors actually issue — not a hand-maintained list — so a permission with no consumer is called out rather than requested:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Organization.Read.All</code></td><td>Application or Delegated</td><td>Read tenant organization details</td></tr><tr><td><code>User.Read.All</code></td><td>Application or Delegated</td><td>Read all user profiles</td></tr><tr><td><code>Group.Read.All</code></td><td>Application or Delegated</td><td>Read all groups and memberships</td></tr><tr><td><code>Application.Read.All</code></td><td>Application or Delegated</td><td>Read all app registrations and service principals</td></tr><tr><td><code>Directory.Read.All</code></td><td>Application or Delegated</td><td>Read organization and hybrid-sync state</td></tr><tr><td><code>RoleManagement.Read.Directory</code></td><td>Application or Delegated</td><td>Read directory roles and PIM role assignments</td></tr><tr><td><code>RoleAssignmentSchedule.Read.Directory</code></td><td>Application or Delegated</td><td>Distinguish active/permanent directory-role schedules</td></tr><tr><td><code>RoleEligibilitySchedule.Read.Directory</code></td><td>Application or Delegated</td><td>Read PIM-eligible directory-role schedules</td></tr><tr><td><code>Policy.Read.All</code></td><td>Application or Delegated</td><td>Read conditional access policies, named locations, authorization policy, cross-tenant access policy</td></tr><tr><td><code>Reports.Read.All</code></td><td>Application or Delegated</td><td>Read per-user MFA registration/capability evidence</td></tr><tr><td><code>AuditLog.Read.All</code></td><td>Application or Delegated</td><td>Read the last 30 days of sign-ins for report-only CA impact, legacy authentication, and privileged-access staleness</td></tr><tr><td><code>AccessReview.Read.All</code></td><td>Application or Delegated</td><td>Read access-review definitions and instances</td></tr><tr><td><code>AdministrativeUnit.Read.All</code></td><td>Application or Delegated</td><td>Read administrative units</td></tr><tr><td><code>Domain.Read.All</code></td><td>Application or Delegated</td><td>Read verified domains</td></tr><tr><td><code>IdentityRiskyUser.Read.All</code></td><td>Application or Delegated</td><td>Read risky-user signals — <strong>also requires an Entra ID P2 licence</strong>; a P1 tenant with the permission granted still returns nothing</td></tr><tr><td><code>Policy.Read.AuthenticationMethod</code></td><td>Application or Delegated</td><td>Read the Verified ID authentication-method configuration (AB#7097)</td></tr><tr><td><code>VerifiedId-Profile.Read.All</code></td><td>Application or Delegated</td><td>Read Verified ID profiles (AB#7097)</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title"><code>IdentityProvider.Read.All</code> is catalogued but disabled because no collector reads it</p><p>Scout&#39;s pre-flight now derives criticality from which collectors actually consume a permission, not from a fixed list. <code>IdentityProvider.Read.All</code> still shows up as a disabled coverage record, but nothing downstream reads its output, so the pre-flight reports it <code>Warn</code> — &quot;queried but NO collector reads the result. Do not grant it.&quot; — rather than asking for it. Sign-in logs are now consumed by Conditional Access impact, legacy-authentication, emergency-access, and privileged-access evidence, so <code>AuditLog.Read.All</code> is part of the full Entra scan.</p></div><p>If you&#39;re signing in as a <strong>user</strong> instead of a service principal, the equivalent least-privilege grant is Entra <strong>directory roles</strong> — not the application permissions above. Azure RBAC, Entra directory roles, and Graph application permissions are three separate systems with different scoping and approvers; pick the directory roles or the app permissions based on whether Scout runs as a user or a service principal, don&#39;t mix them.</p><p><code>Directory Readers</code> + <code>Security Reader</code> covers most Entra collectors; the following need additional roles of their own, evaluated least-privileged first:</p><ul><li><p>MFA registration and sign-in-log evidence needs <code>Reports Reader</code> and/or <code>Security Reader</code> as listed in the live query catalog; delegated OAuth scopes are still required.</p></li><li><p>Active-versus-eligible PIM schedules need <code>Privileged Role Administrator</code> or <code>Global Reader</code>.</p></li><li><p>Access reviews need <code>Identity Governance Administrator</code> or <code>Global Reader</code>.</p></li><li><p><code>CrossTenantAccess</code> needs <code>Security Administrator</code> or <code>Tenant Governance Administrator</code> — evaluate both before reaching for <code>Global Reader</code>, which Microsoft classifies as a privileged role.</p></li><li><p><code>VerifiedIDConfiguration</code> (reads <code>Policy.Read.AuthenticationMethod</code>, AB#7097) needs <code>Authentication Policy Administrator</code> (or <code>Global Reader</code>, but <code>Authentication Policy Administrator</code> is the less-privileged of the two, and <code>Security Reader</code> does <strong>not</strong> cover this endpoint despite covering most of the rest).</p></li><li><p><code>VerifiedIDProfiles</code> (reads <code>VerifiedId-Profile.Read.All</code>, AB#7097) needs <code>Authentication Policy Administrator</code> — Microsoft&#39;s documented least-privileged role for this endpoint.</p></li></ul><p><code>Authentication Policy Administrator</code> covers both Verified ID collectors, so the full user-auth grant depends on the selected evidence surfaces. Run <code>-PermissionAudit -IncludeEntraPermissions</code> to obtain the exact per-collector impact for the current token rather than treating one broad role bundle as universally sufficient. See <a href="./../assessment/assessment-permissions.html">Assessment Permissions</a>.</p><h2 id="optional-non-azure-identity-sources" tabindex="-1">Optional non-Azure identity sources <a class="header-anchor" href="#optional-non-azure-identity-sources" aria-label="Permalink to &quot;Optional non-Azure identity sources&quot;">​</a></h2><ul><li><strong>Okta:</strong> <code>-IncludeOkta</code> needs a read-only Okta API token or OAuth grant able to read apps and assignments, policies/rules, zones, factors/users, administrator roles, directories/agents, ThreatInsight, and System Log SSO events. Each denied endpoint is isolated and recorded. The token itself is never persisted.</li><li><strong>Entra Connect / AD:</strong> <code>-IncludeOnPremisesIdentity</code> needs local read access to ADSync cmdlets, the ADSync/Connect Health services, and the ActiveDirectory cmdlets. It grants nothing and makes no changes; missing modules or host access are recorded as Not assessed.</li></ul><div class="warning custom-block"><p class="custom-block-title">Complete delegated Entra collection can require a second device-code confirmation</p><p><code>Get-AzAccessToken</code> can select the Microsoft Graph audience but cannot request arbitrary delegated scopes. When an interactive user run selects Entra evidence, Scout therefore uses the official <code>Microsoft.Graph.Authentication</code> module to request the enabled catalog&#39;s exact read scopes through device code. Bearer and refresh tokens stay in the SDK cache; Scout retains only provider/scope metadata keyed by tenant, account, cloud, and scope set. Service principals and managed identities do not use device code; they continue to use the selected Az context and must have the equivalent Graph <strong>application</strong> permissions admin-consented. Directory roles and OAuth scopes are both enforced—neither one substitutes for the other.</p></div><h2 id="licence-tiers-—-what-a-permission-cannot-buy-you" tabindex="-1">Licence tiers — what a permission cannot buy you <a class="header-anchor" href="#licence-tiers-—-what-a-permission-cannot-buy-you" aria-label="Permalink to &quot;Licence tiers — what a permission cannot buy you&quot;">​</a></h2><p><strong>Scout runs, and produces its full report, on a tenant with no premium Entra licence at all.</strong> Licence tier changes how much of the <em>identity</em> picture can be filled in. It changes nothing about the Azure resource inventory, the CAF/WAF assessment, policy and compliance state, or Defender findings — those are Azure control-plane reads governed by <code>Reader</code>, not by Entra licensing.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Requires</th><th>Without it</th></tr></thead><tbody><tr><td>Resource inventory, CAF/WAF assessment, policy &amp; compliance, Defender</td><td>Azure <code>Reader</code> only</td><td>Full coverage</td></tr><tr><td>Users, groups, apps, service principals, directory roles, domains, administrative units</td><td>Entra ID <strong>Free</strong></td><td>Full coverage</td></tr><tr><td>Conditional Access policies, named locations, cross-tenant access</td><td>Entra ID <strong>P1</strong></td><td>Reported <em>Not assessed</em> — Conditional Access does not exist to read on a Free tenant</td></tr><tr><td>Risky users / Identity Protection (<code>IdentityRiskyUser.Read.All</code>)</td><td>Entra ID <strong>P2</strong></td><td>Reported <em>Not assessed</em>. <strong>Granting the permission does not help</strong></td></tr><tr><td>PIM eligibility and activation (<code>PrivilegedAccess.Read.AzureResources</code>)</td><td>Entra ID <strong>P2</strong></td><td>Reported <em>Not assessed</em>; standing role assignments are still read</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">A licence boundary is not a permission failure</p><p>Scout reads <code>subscribedSkus</code> and checks the tenant&#39;s licence before deciding a verdict. A licence-gated permission on an unlicensed tenant reports <strong><code>NOT LICENSED</code></strong>, names the product, and states that granting the permission will not populate those collectors — it does <strong>not</strong> report <code>DENIED</code> and send you to grant something that cannot work.</p><p>Most tenants do not carry P2, so this was previously the <em>common</em> case being reported as an error.</p><p>The licence check is three-state — licensed / not licensed / <strong>could not tell</strong>. Only a definitive &quot;not licensed&quot; softens the verdict; if <code>subscribedSkus</code> itself cannot be read the verdict stays <code>Fail</code>, because silently downgrading a genuine denial would hide a real problem.</p></div><p>Either way the affected collectors are reported as <strong>Not assessed</strong> and named in the report. A gap you chose not to license is still a gap — it is never a pass and never a zero.</p><h2 id="pre-flight-validation" tabindex="-1">Pre-flight Validation <a class="header-anchor" href="#pre-flight-validation" aria-label="Permalink to &quot;Pre-flight Validation&quot;">​</a></h2><p>The <code>Test-AZSCPermissions</code> function runs automatically before extraction (unless <code>-SkipPermissionCheck</code> is set):</p><table tabindex="0"><thead><tr><th>Check</th><th>Severity</th><th>Behavior</th></tr></thead><tbody><tr><td>ARM: Subscription Enumeration</td><td><strong>Fail</strong></td><td>Stops ARM extraction if no subscriptions accessible</td></tr><tr><td>ARM: Role Assignment Read (per subscription)</td><td><strong>Fail</strong></td><td>That subscription&#39;s inventory is incomplete without <code>Reader</code></td></tr><tr><td>Graph: each permission with a consumer</td><td><strong>Fail</strong></td><td>Names the exact collectors that will come back empty, and the permission to grant</td></tr><tr><td>Graph: licence-gated permission on an unlicensed tenant</td><td><strong>Warn</strong></td><td><code>NOT LICENSED</code> — names the product; granting the permission would not help</td></tr><tr><td>Graph: each permission with no consumer</td><td><strong>Warn</strong></td><td>Reports it as unused — &quot;do not grant&quot; — rather than requesting it</td></tr></tbody></table><h3 id="reading-the-three-verdicts" tabindex="-1">Reading the three verdicts <a class="header-anchor" href="#reading-the-three-verdicts" aria-label="Permalink to &quot;Reading the three verdicts&quot;">​</a></h3><p>They look alike and mean different things:</p><table tabindex="0"><thead><tr><th>Verdict</th><th>Meaning</th><th>Action</th></tr></thead><tbody><tr><td><code>[FAIL] … DENIED — N collectors will be empty</code></td><td>A real gap; granting fixes the coverage</td><td><strong>Grant it</strong></td></tr><tr><td><code>[WARN] … NOT LICENSED — requires &lt;product&gt;</code></td><td>A licence boundary, not a misconfiguration</td><td><strong>None</strong>, unless you intend to license that tier</td></tr><tr><td><code>[WARN] … queried but NO collector reads the result</code></td><td>Scout probes something nothing consumes</td><td><strong>Do not grant it</strong></td></tr></tbody></table><p><strong>The output is a per-collector impact table, not a bare READY / PARTIAL / INSUFFICIENT verdict.</strong> Criticality is derived from which collectors consume which permission, so there is no separate hardcoded list of &quot;critical&quot; permissions to fall out of date. A denied Graph permission also reaches PowerShell&#39;s warning stream now, not only a coloured console write — so an automated caller (CI, a scheduled Automation Account run) can detect and act on it, not just a human watching the console. See <a href="./troubleshooting.html">Troubleshooting</a> for what to do with a <code>Fail</code>.</p><h2 id="scope-based-gating" tabindex="-1">Scope-Based Gating <a class="header-anchor" href="#scope-based-gating" aria-label="Permalink to &quot;Scope-Based Gating&quot;">​</a></h2><p>Permission checks respect the <code>-Scope</code> parameter:</p><ul><li><code>ArmOnly</code> — Only ARM checks run (Graph checks are skipped entirely)</li><li><code>EntraOnly</code> — Only Graph checks run (ARM checks are skipped entirely)</li><li><code>All</code> — Both ARM and Graph checks run</li></ul><h2 id="remediation" tabindex="-1">Remediation <a class="header-anchor" href="#remediation" aria-label="Permalink to &quot;Remediation&quot;">​</a></h2><p>If the permission checker reports failures:</p><ol><li>For ARM: Ensure <code>Reader</code> role is assigned on target subscriptions</li><li>For Graph: Grant the required Microsoft Graph API permissions to your app registration or user account</li><li>Re-run with the appropriate credentials</li></ol><div class="warning custom-block"><p class="custom-block-title">Verification status</p><p>This page is documentation analysis backed by Microsoft&#39;s published role and permission references, not a tested result. No run has been performed against a <code>Reader</code>-only principal (or the Entra/Graph minimum-privilege grants above) to confirm every collector still returns data. The reasoning is sound and Microsoft-doc-backed, but treat it as <strong>probable, not proven</strong> until a live comparison run exists.</p></div><h2 id="a-different-narrower-model-for-the-caf-waf-assessment-platform" tabindex="-1">A different, narrower model for the CAF/WAF assessment platform <a class="header-anchor" href="#a-different-narrower-model-for-the-caf-waf-assessment-platform" aria-label="Permalink to &quot;A different, narrower model for the CAF/WAF assessment platform&quot;">​</a></h2><p>Everything above is the <strong>inventory mode</strong> permission model (<code>Invoke-AzureScout</code> / <code>Test-AZSCPermissions</code>). <strong>Assessment mode</strong> (<code>-Assessment</code> / <code>Test-ScoutPermission</code>) uses a different, narrower model — do not conflate the two:</p><table tabindex="0"><thead><tr><th></th><th>Inventory mode (<code>Test-AZSCPermissions</code>)</th><th>Assessment mode (<code>Test-ScoutPermission</code>)</th></tr></thead><tbody><tr><td>ARM scope</td><td><code>Reader</code> on each target <strong>subscription</strong></td><td><code>Reader</code> at the <strong>tenant-root management group</strong></td></tr><tr><td>Graph</td><td>Up to 9 permissions, required for <code>-Scope All</code>/<code>EntraOnly</code></td><td>Not required by any assessment out of the box — governance data (<code>CAF: Azure Landing Zone</code>, <code>Management</code>, <code>Identity</code>, <code>Scout: Governance Baseline</code>, <code>Policy</code>) is collected natively via ARM/Resource Graph. 4 Graph permissions apply <strong>only</strong> if you opt one of those 5 into the legacy <code>AzGovViz</code> ingestor instead</td></tr><tr><td>Live-validated?</td><td>Yes — both ARM and Graph checks call live endpoints</td><td>ARM check is live; the 4 Graph permissions are listed as an <strong>unverified checklist</strong> (<code>Ok = $null</code>), not actually tested</td></tr></tbody></table><p>Full matrix (every assessment, minimum RBAC, which need Graph, and the <code>PrivilegedAccess.Read.AzureResources</code> / Entra P2 nuance): <a href="./../assessment/assessment-permissions.html">Auth &amp; permissions per scan type</a>.</p>',48)])])}const m=t(a,[["render",i]]);export{u as __pageData,m as default};
